import * as THREE from 'three';
export class FPSControls{constructor(camera,dom,collide){this.camera=camera;this.dom=dom;this.collide=collide;this.keys={};this.yaw=0;this.pitch=0;this.locked=false;this.speed=3.4;this.run=false;this.mobile={x:0,y:0};window.addEventListener('keydown',e=>{this.keys[e.code]=true;if(e.code==='ShiftLeft')this.run=true});window.addEventListener('keyup',e=>{this.keys[e.code]=false;if(e.code==='ShiftLeft')this.run=false});dom.addEventListener('click',()=>dom.requestPointerLock?.());document.addEventListener('pointerlockchange',()=>this.locked=document.pointerLockElement===dom);document.addEventListener('mousemove',e=>{if(this.locked)this.look(e.movementX,e.movementY)});this.bindTouch()}
look(x,y){this.yaw-=x*.0022;this.pitch-=y*.0022;this.pitch=Math.max(-1.35,Math.min(1.35,this.pitch));this.camera.rotation.set(this.pitch,this.yaw,0,'YXZ')}
bindTouch(){let zone=document.getElementById('look-zone'),last=null;zone?.addEventListener('touchstart',e=>{last=e.touches[0]},{passive:true});zone?.addEventListener('touchmove',e=>{if(!last)return;let t=e.touches[0];this.look((t.clientX-last.clientX)*1.6,(t.clientY-last.clientY)*1.6);last=t},{passive:true});zone?.addEventListener('touchend',()=>last=null);let j=document.getElementById('joystick'),stick=document.getElementById('stick');j?.addEventListener('touchmove',e=>{let r=j.getBoundingClientRect(),t=e.touches[0],x=(t.clientX-r.left-52)/45,y=(t.clientY-r.top-52)/45,len=Math.hypot(x,y);if(len>1){x/=len;y/=len}this.mobile={x,y};stick.style.transform=`translate(${x*28}px,${y*28}px)`;e.preventDefault()},{passive:false});j?.addEventListener('touchend',()=>{this.mobile={x:0,y:0};stick.style.transform=''})}
update(dt){let f=(this.keys.KeyW?1:0)-(this.keys.KeyS?1:0)+(-this.mobile.y),s=(this.keys.KeyD?1:0)-(this.keys.KeyA?1:0)+this.mobile.x;if(!f&&!s)return false;let v=this.speed*(this.run?1.65:1)*dt,dir=new THREE.Vector3(Math.sin(this.yaw)*f+Math.cos(this.yaw)*s,0,Math.cos(this.yaw)*f-Math.sin(this.yaw)*s).normalize().multiplyScalar(v);let next=this.camera.position.clone().add(dir);if(!this.collide(next))this.camera.position.copy(next);return true}}
